"use strict";
// Cover effects applied before the payload is written: blur, lens flare, bloom, chromatic aberration, vignette, film grain.
const {clamp,hash2,luminance}=require("./math.js");
const EFFECTS=[["blur","Gaussian blur"],["flare","Lens flare"],["bloom","Bloom / glow"],["chroma","Chromatic aberration"],["vignette","Vignette"],["grain","Film grain"]];
function boxPass(a,w,h,n,r,horizontal){if(r<1)return a;const out=new Uint8Array(a),m=Math.min(3,n),len=horizontal?w:h,lines=horizontal?h:w,win=2*r+1;for(let L=0;L<lines;L++)for(let k=0;k<m;k++){const idx=t=>(horizontal?(L*w+t):(t*w+L))*n+k;let sum=0;for(let t=-r;t<=r;t++)sum+=a[idx(clamp(t,0,len-1))];for(let t=0;t<len;t++){out[idx(t)]=Math.round(sum/win);sum+=a[idx(Math.min(len-1,t+r+1))]-a[idx(Math.max(0,t-r))]}}return out}
function gaussian(a,w,h,n,radius){const r=Math.max(0,Math.round(radius/Math.sqrt(3)));if(r<1)return new Uint8Array(a);let o=a;for(let i=0;i<3;i++){o=boxPass(o,w,h,n,r,true);o=boxPass(o,w,h,n,r,false)}return o}
function screen(c,l){return 255-(255-c)*(1-clamp(l,0,1))}
function flare(a,w,h,n,amt,seed){const out=new Uint8Array(a),R=Math.max(w,h),fx=w*(.18+.3*hash2(1,2,seed)),fy=h*(.1+.2*hash2(3,4,seed)),cx=w/2,cy=h/2,k=amt/100,ghosts=[[-.35,.05,[.5,.8,1]],[.35,.03,[1,.6,.3]],[.6,.07,[.4,1,.6]],[.9,.04,[.8,.5,1]],[1.3,.1,[.3,.6,1]]];for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*n;if(n>3&&a[i+3]===0)continue;const dx=x-fx,dy=y-fy,d=Math.hypot(dx,dy);let r=0,g=0,b=0;const core=Math.exp(-((d/(R*.05))**2)),glow=Math.exp(-d/(R*.18))*.45,ring=Math.exp(-(((d-R*.22)/(R*.006))**2))*.18,streak=Math.exp(-((dy/(R*.004))**2))*Math.exp(-Math.abs(dx)/(R*.5))*.7;r+=core+glow*1+ring*.9+streak*.6;g+=core+glow*.75+ring*.7+streak*.8;b+=core+glow*.45+ring*1+streak*1;for(const[t,s,c]of ghosts){const gx=fx+(cx-fx)*2*t,gy=fy+(cy-fy)*2*t,gd=Math.hypot(x-gx,y-gy)/(R*s),e=gd<1?.16*(1-gd*gd*gd):0;r+=e*c[0];g+=e*c[1];b+=e*c[2]}out[i]=screen(a[i],r*k);if(n>1)out[i+1]=screen(a[i+1],g*k);if(n>2)out[i+2]=screen(a[i+2],b*k)}return out}
function bloom(a,w,h,n,amt){const bright=new Uint8Array(a.length);for(let i=0;i<a.length;i+=n){const l=luminance(a[i],a[i+1]??a[i],a[i+2]??a[i]),t=clamp((l-150)/105,0,1);for(let k=0;k<Math.min(3,n);k++)bright[i+k]=a[i+k]*t;if(n>3)bright[i+3]=a[i+3]}const bl=gaussian(bright,w,h,n,Math.max(w,h)*.012*(.5+amt/50)),out=new Uint8Array(a),k=amt/100*1.4;for(let i=0;i<a.length;i+=n)for(let c=0;c<Math.min(3,n);c++)out[i+c]=screen(a[i+c],bl[i+c]/255*k);return out}
function chroma(a,w,h,n,amt){const out=new Uint8Array(a),cx=w/2,cy=h/2,R=Math.hypot(cx,cy),s=amt/100*.012;if(n<3)return out;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*n,dx=x-cx,dy=y-cy,sx=x=>clamp(Math.round(x),0,w-1),sy=y=>clamp(Math.round(y),0,h-1),f=Math.hypot(dx,dy)/R;out[i]=a[(sy(y+dy*s*f)*w+sx(x+dx*s*f))*n];out[i+2]=a[(sy(y-dy*s*f)*w+sx(x-dx*s*f))*n+2]}return out}
function vignette(a,w,h,n,amt){const out=new Uint8Array(a),cx=w/2,cy=h/2,R=Math.hypot(cx,cy),k=amt/100*.85;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*n,t=clamp((Math.hypot(x-cx,y-cy)/R-.35)/.65,0,1),f=1-k*t*t*(3-2*t);for(let c=0;c<Math.min(3,n);c++)out[i+c]=Math.round(a[i+c]*f)}return out}
function grain(a,w,h,n,amt,seed){const out=new Uint8Array(a),s=amt*.5;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*n,v=(hash2(x,y,seed)+hash2(x,y,seed+7)-1)*s;for(let c=0;c<Math.min(3,n);c++)out[i+c]=clamp(Math.round(a[i+c]+v),0,255)}return out}
function apply(src,w,h,n,fx,seed){let a=src;const on=k=>fx[k]&&fx[k].on&&fx[k].amount>0;if(on("blur"))a=gaussian(a,w,h,n,fx.blur.amount/100*Math.max(w,h)*.02);if(on("bloom"))a=bloom(a,w,h,n,fx.bloom.amount);if(on("flare"))a=flare(a,w,h,n,fx.flare.amount,seed);if(on("chroma"))a=chroma(a,w,h,n,fx.chroma.amount);if(on("vignette"))a=vignette(a,w,h,n,fx.vignette.amount);if(on("grain"))a=grain(a,w,h,n,fx.grain.amount,seed);return a}
module.exports={EFFECTS,apply};
